<?php $product=query('SELECT * FROM products WHERE id=? AND active=1',[(int)($_GET['id']??0)])->fetch();if(!$product){http_response_code(404);?><p class="b2b-error">Artikal nije pronađen.</p><?php return;}$override=query('SELECT * FROM partner_prices WHERE partner_id=? AND product_id=?',[$partner['id'],$product['id']])->fetch()?:null;$q=null;try{$q=partnerQuote($product,$partner,$override);}catch(RuntimeException $e){?><p class="b2b-error"><?=e($e->getMessage())?></p><?php }?>
<p><a href="partner.php">← Poslovni katalog</a></p><section class="b2b-panel b2b-product-detail"><div><img class="b2b-detail-image" src="<?=e(imageSource($product['image_url'],$product['sku']))?>" alt="<?=e($product['name'])?>"><?php foreach(query('SELECT image_url FROM product_images WHERE product_id=? ORDER BY sort_order,id',[$product['id']])->fetchAll() as $image):?><img class="b2b-detail-extra" src="<?=e(imageSource($image['image_url'],$product['sku']))?>" alt="<?=e($product['name'])?> — dodatna fotografija" loading="lazy"><?php endforeach;?></div><div><p class="b2b-kicker"><?=e($product['sku'])?></p><h1><?=e($product['name'])?></h1><p><?=nl2br(e((string)$product['description']))?></p><?php if($q):?><p class="b2b-detail-price"><?=partnerMoney($q['unit'])?></p><p><?=e(partnerMode($q['mode']))?> <?=decimal($q['rate'])?>%<br>Osnovica: <?=partnerMoney($q['base'])?><br><?=$q['mode']==='discount'?'Vaš popust':'Marža / dodatak'?>: <?=partnerMoney($q['adjustment'])?> / kom.</p><?php if($q['override']):?><p class="b2b-status">Individualni uslovi za ovaj artikal</p><?php endif;endif;if(inventoryEnabled()):?><p>Dostupno: <?=(int)$product['stock']?> kom.</p><?php endif;?><form method="post"><?=csrf()?><input type="hidden" name="action" value="cart_add"><input type="hidden" name="product_id" value="<?=(int)$product['id']?>"><label for="detail-quantity">Količina</label><input id="detail-quantity" type="number" name="quantity" min="1" max="100" value="1" required><button <?=!$q||!productOrderable($product)?'disabled':''?>>Dodaj u poslovnu korpu</button></form></div></section>
